import sys, json, random
sys.path.insert(0,'/app/work')
import ref, gen2
rnd = random.Random(99)
counts = []
for it in range(120):
    req = gen2.gen_request(rnd, nf=rnd.randint(1,3), natoms=rnd.randint(1,10),
                           k=rnd.randint(1,3), nrows=rnd.randint(0,10), ntr=rnd.randint(1,5))
    schema = req['schema']
    for part in ('train','probes','queries'):
        for tr in req[part]:
            for r_ in tr['rows']:
                vals = []
                for f in schema:
                    if f['type'] in ('TIME','SIZE','COUNT'): vals.append(rnd.choice([f['min'], f['max']]))
                    elif f['type'] == 'ID': vals.append(rnd.choice(f['values'][:2]))
                    else: vals.append(rnd.random() < 0.5)
                r_['values'] = vals
    classes, qout = ref.ref_process(req)
    counts.append((len(classes), sum(c['members'] for c in classes)))
import collections
print('classes histogram', collections.Counter(c for c,_ in counts).most_common(8))
print('max members', max(m for _,m in counts), 'total with classes', sum(1 for c,_ in counts if c))
EOF
